INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT136-S2-Q1$batch02$, 136, 2, 1, $batch02$Flaw$batch02$, $batch02$Mayor: There has been a long debate in city council about how to accommodate projected increases in automobile traffic. Today, our choice is clear: either we adopt my plan to build a new expressway, or we do nothing. Doing nothing is not a viable option because our existing system of roads would be in gridlock within ten years given even a conservative estimate of future traffic levels. City council should therefore adopt my plan.$batch02$, $batch02$The reasoning in the mayor's argument is most vulnerable to which one of the following criticisms?$batch02$, $batch02$E$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=136 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q1$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$It bases a projection only on conservative estimates rather than considering a wider range of estimates.$batch02$, $batch02$Strengthens, if anything$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q1$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$It takes for granted that the options it considers are mutually exclusive.$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q1$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$It fails to consider the possibility that the rate of increase in traffic will start to diminish after ten years.$batch02$, $batch02$No Impact$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q1$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$It fails to address the issue of the cost of traffic gridlock to the city's economy.$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q1$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$It presents a choice that is limited to two options, without giving reasons for not considering any other options.$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q1$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q1$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$The council should adopt the mayor's expressway plan.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$The only options are the expressway or nothing, and doing nothing leads to gridlock.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Grant that doing nothing is a bad idea. Does that make the expressway the answer? Only if there are no other options. What about better public transit, widening existing roads, or changing traffic signals? The mayor narrows the menu to two items, rejects one, and declares the other the winner.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Expect the false choice answer: the argument ignores other options.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT136-S2-Q1$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$A conservative estimate already predicts gridlock. Higher estimates would make doing nothing look even worse.$batch02$), ($batch02$B$batch02$, $batch02$Building an expressway and doing nothing really are mutually exclusive, so taking that for granted is fine. The problem is not that the two options overlap but that they are *not the only ones*. Watch the difference between "exclusive" and "exhaustive."$batch02$), ($batch02$C$batch02$, $batch02$Gridlock arrives within ten years either way. A slower increase afterward does not rescue the do-nothing option or help any alternative.$batch02$), ($batch02$D$batch02$, $batch02$The economic cost of gridlock would, if anything, add to the case against doing nothing. It does not reveal the missing options.$batch02$), ($batch02$E$batch02$, $batch02$The mayor offers only two choices and never explains why others are off the table. Eliminating one of two options proves the other only if those two are all there are.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT136-S2-Q1$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
